const output = $json.output;
const allItems = [];

// Long form'ları ekle
if (output.long_form) {
  output.long_form.forEach((item) => {
    allItems.push({
      json: {
        tarih: item.publish_date,
        baslik: item.title,
        aciklama: item.description,
        format: 'long',
        'ana-tema': item.prompt,
        'sahne-prompt': '',
        durum: 'planlandı'
      }
    });
  });
}

// Shorts'ları ekle
if (output.shorts) {
  output.shorts.forEach((item) => {
    allItems.push({
      json: {
        tarih: item.publish_date,
        baslik: item.title,
        aciklama: item.description,
        format: 'short',
        'ana-tema': item.prompt,
        'sahne-prompt': '',
        durum: 'planlandı'
      }
    });
  });
}

return allItems;

const aylar = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 
               'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık'];

// TSİ için UTC+3
const now = new Date();
const tpiTime = new Date(now.getTime() + (3 * 60 * 60 * 1000));

const gun = tpiTime.getUTCDate();
const ay = aylar[tpiTime.getUTCMonth()];
const yil = tpiTime.getUTCFullYear();

const bugunTarih = `${gun} ${ay} ${yil}`;

return [{ json: { bugunTarih } }];

const row = $input.first().json;
const title = String(row.baslik || row.title || '').trim();
const desc = String(row.aciklama || row.description || '').trim();
const format = String(row.format || 'short').toLowerCase();
const maxTitle = format.includes('long') ? 60 : 40;
const issues = [];
if (!title) issues.push('baslik bos');
else if (title.length > maxTitle) issues.push(`baslik ${title.length}>${maxTitle}`);
if (!desc) issues.push('aciklama bos');
else if (desc.length < 20) issues.push('aciklama cok kisa');
return [{ json: { ...row, seo_ok: issues.length === 0, seo_issues: issues.join('; ') || 'ok' } }];
